// ensureRideHistory (re)creates the ride_history table when a query fails
// because it doesn't exist, and reports whether the query should be retried.
func (d *database) ensureRideHistory(err error) bool {
	if mysqlErr, ok := err.(*mysql.MySQLError); ok && mysqlErr.Number == 1146 {
		if _, err := d.db.Exec(rideHistorySchema); err != nil {
			return false
		}
		return true
	}
	return false
}

// ListRideHistory returns the most recent rides first, plus the total count.
func (d *database) ListRideHistory(ctx context.Context) ([]RideHistoryEntry, int, error) {
	d.logger.For(ctx).Info("Loading ride history")

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	query := "SELECT id, pickup_name, dropoff_name, request_time, driver_plate, fare " +
		"FROM ride_history ORDER BY request_time DESC, id DESC"
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.Key("sql.query").String(query),
	)
	defer span.End()

	rows, err := d.db.Query(query)
	if err != nil {
		if !d.ensureRideHistory(err) {
			return nil, 0, err
		}
		if rows, err = d.db.Query(query); err != nil {
			return nil, 0, err
		}
	}
	defer rows.Close()

	rides := []RideHistoryEntry{}
	for rows.Next() {
		var e RideHistoryEntry
		if err := rows.Scan(&e.ID, &e.PickupName, &e.DropoffName, &e.RequestTime,
			&e.DriverPlate, &e.Fare); err != nil {
			return nil, 0, err
		}
		rides = append(rides, e)
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}
	return rides, len(rides), nil
}

func (d *database) CreateRideHistory(ctx context.Context, e *RideHistoryEntry) (int64, error) {
