	query := "INSERT INTO ride_history (pickup_name, dropoff_name, request_time, driver_plate, fare) " +
		"VALUES (?, ?, ?, ?, ?)"
	args := []interface{}{e.PickupName, e.DropoffName, e.RequestTime.UTC(), e.DriverPlate, e.Fare}
	res, err := d.db.Exec(query, args...)
	if err != nil {
		if !d.ensureRideHistory(err) {
			return 0, err
		}
		if res, err = d.db.Exec(query, args...); err != nil {
			return 0, err
		}
	}
	return res.LastInsertId()
}

