func (d *database) UpdateRideHistory(ctx context.Context, id int64, plate string, fare float64) (bool, error) {
	d.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", id))
	// Use an existence check rather than RowsAffected, which is 0 when the
	// values are unchanged.
	query := "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
