import {useCallback, useEffect, useRef, useState} from "react";
import {apiGet, apiRequest} from "../services/http.ts";
import {RideHistoryEntry, RideHistoryList} from "../types/rideHistory.ts";
import {Log} from "./useLogs.tsx";
import {parseDriverFare, parseDriverPlate} from "./useGetRequestArrival.tsx";

const RIDE_HISTORY_PATH = '/ride-history';

export const useRideHistory = (logs: Log[]) => {
    const [history, setHistory] = useState<RideHistoryList>({rides: [], total: 0});
    // request ID -> promise of the ride-history entry ID created for that request
    const createdRef = useRef(new Map<number, Promise<number | undefined>>());
    const patchedRef = useRef(new Set<number>());

    const refresh = useCallback(async () => {
        try {
            const list = await apiGet<RideHistoryList>(RIDE_HISTORY_PATH);
            setHistory({rides: list.rides ?? [], total: list.total ?? 0});
        } catch (e) {
            console.error('cannot load ride history', e);
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    // Creates the ride-history entry for a dispatched request.
    const createEntry = useCallback((requestID: number, pickupName: string, dropoffName: string) => {
        const created = (async () => {
            try {
                const entry = await apiRequest<RideHistoryEntry>('POST', RIDE_HISTORY_PATH, {
                    pickupName,
                    dropoffName,
                    requestTime: new Date().toISOString(),
                });
                await refresh();
                return entry.id;
            } catch (e) {
                console.error('cannot create ride history entry', e);
                return undefined;
            }
        })();
        createdRef.current.set(requestID, created);
        return created;
    }, [refresh]);

    // When the driver notification (plate + fare) of a request arrives,
    // update its ride-history entry once.
    useEffect(() => {
        logs.forEach(log => {
            if (patchedRef.current.has(log.requestID)) return;
            const created = createdRef.current.get(log.requestID);
            if (!created) return;

            let plate: string | undefined;
            let fare: number | undefined;
            log.entries.filter(e => e.service === 'driver').forEach(e => {
                plate = plate ?? parseDriverPlate(e.status);
                fare = fare ?? parseDriverFare(e.status);
            });
            if (plate === undefined || fare === undefined) return;

            patchedRef.current.add(log.requestID);
            created.then(async id => {
                if (id === undefined) return;
                try {
                    await apiRequest('PATCH', RIDE_HISTORY_PATH, {id, driverPlate: plate, fare});
                    await refresh();
                } catch (e) {
                    console.error('cannot update ride history entry', e);
                    patchedRef.current.delete(log.requestID);
                }
            });
        });
    }, [logs, refresh]);

    return {history, createEntry};
};
EOF
